interface User {
  id: string;
  email: string;
  name: string;
  passwordHash: string;
}

type PublicUser = Omit<User, "passwordHash" | "email">; // { id; name }
type UserPreview = Pick<User, "id" | "name">;          // same shape, other direction
type UsersById = Record<string, PublicUser>;            // lookup table

interface Settings { theme?: "light" | "dark"; pageSize?: number }
type ResolvedSettings = Required<Settings>;             // both keys mandatory
type FrozenSettings = Readonly<ResolvedSettings>;       // no reassignment
